import React, { useState, useEffect } from "react";
import "./clippreview.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faScissors, faPlay, faPause, faDownload } from "@fortawesome/free-solid-svg-icons";

function ClipPreview({ videoUrl, videoThumbnail, clips }) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [clipStart, setClipStart] = useState(0);
  const [clipEnd, setClipEnd] = useState(0);

  // Toggle play/pause logic
  const handlePlayPause = () => {
    setIsPlaying((prev) => !prev);
  };

  // Handle clip creation logic (this can be integrated with your backend logic)
  const handleClip = (start, end) => {
    if (start < 0 || end <= start) {
      alert("Please enter a valid clip range (end > start).");
      return;
    }
    alert("Clip created from ${start} to ${end} seconds!");
  };

  useEffect(() => {
    // Here you would fetch or use the clips received from the backend
    // For now, it's passed as a prop to the component
  }, [clips]);

  return (
    <div className="clipping-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content */}
      <main className="main-content">
        {/* Clipper Section */}
        <section className="clipper-section">
          <button className="clipper-btn">Clipper</button>

          {/* Long Video Section */}
          <div className="long-video">
            <h2>Your long video</h2>
            <div className="video-preview">
              {videoUrl ? (
                <video src={videoUrl} controls className="preview-video" />
              ) : (
                <img
                  src={videoThumbnail || "https://via.placeholder.com/300x200"}
                  alt="Video Thumbnail"
                  className="preview-image"
                />
              )}
            </div>
          </div>

          {/* Viral Clips Section */}
          <div className="viral-clips">
            <h3>Your Viral Clips</h3>
            <div className="clip-thumbnails">
              {clips.map((clip, index) => (
                <div key={index} className="clip-thumbnail-container">
                  <img
                    src={clip.thumbnail || "https://via.placeholder.com/150"}
                    alt={"Clip ${index + 1}"}

                    className="clip-thumbnail"
                  />
                  <div className="clip-actions">
                    <button onClick={() => handleClip(clip.start, clip.end)}>
                      <FontAwesomeIcon icon={faScissors} /> Clip
                    </button>
                    <button>
                      <FontAwesomeIcon icon={faPlay} /> Play
                    </button>
                    <button>
                      <FontAwesomeIcon icon={faDownload} /> Download
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}

export default ClipPreview;
